  footer?: SlotProp<TableContext<TData>, SlotElementProps>;
  footerRow?: SlotProp<TableContext<TData>, SlotElementProps>;
  footerCell?: SlotProp<
    TableContext<TData> & { header: Header<TData, unknown> },
    SlotElementProps
