import type { RowData } from "@tanstack/react-table";

import { DataTableBody } from "@/components/data-table/body/data-table-body";
import { DataTableFooter } from "@/components/data-table/footer/data-table-footer";
import { DataTableHead } from "@/components/data-table/head/data-table-head";
import { TableProgressBar } from "@/components/table/table-progress-bar";
import { Table } from "@/components/ui/table";
import { useColumnSizeVars } from "@/hooks/table/use-column-size-vars";
import type { TableCoreInstance } from "@/hooks/table/use-table-core";
import { cn } from "@/lib/utils";
import { resolveSlotProp } from "@/types/table";

interface DataTableContainerProps<TData extends RowData> {
  table: TableCoreInstance<TData>;
}

/** Scroll box that owns sticky positioning — the analog of MRT_TableContainer. */
export function DataTableContainer<TData extends RowData>({
  table,
}: DataTableContainerProps<TData>) {
  const { showProgressBars } = table.getState();
  const containerProps = resolveSlotProp(table.options.slotProps.container, {
    table,
  });

  // Ghim cột tính `left`/`right` từ `column.getSize()`, nên chỉ khớp khi trình
  // duyệt dùng đúng width đó — tức phải `table-layout: fixed` + width tổng.
  //
  // Chỉ bật khi thật cần: fixed layout ép mọi cột về size khai báo (mặc định
  // 150px), làm mất tỉ lệ tự nhiên. Ghim đúng một cột ở mép thì offset luôn
  // bằng 0 nên không cần; từ cột thứ hai trở đi offset mới cộng dồn.
  const pinning = table.getState().columnPinning;
  const hasExplicitSizing =
    table.options.enableColumnResizing === true ||
    (pinning.left?.length ?? 0) > 1 ||
    (pinning.right?.length ?? 0) > 1;

  // Gán MỘT LẦN lên container — mỗi cell tham chiếu qua calc(var(...)) nên
  // trình duyệt tự cascade width khi resize, không cần React patch từng cell.
  // Xem chú thích trong useColumnSizeVars để biết lý do.
  const columnSizeVars = useColumnSizeVars(table);

  return (
    <div
      data-slot="data-table-container"
      {...containerProps}
      style={{ ...columnSizeVars, ...containerProps?.style }}
      className={cn(
        // `min-h-0 flex-1` makes this the scroll region inside the paper's flex
        // column; without it the container grows to content height and the page
        // scrolls instead, which breaks sticky headers and infinite scroll.
        "relative min-h-0 flex-1 h-full flex flex-col rounded-md border",
        containerProps?.className,
      )}
    >
      <TableProgressBar visible={showProgressBars} />
      <Table
        style={
          hasExplicitSizing
            ? {
                tableLayout: "fixed",
                width: "calc(var(--table-total-size) * 1px)",
              }
            : undefined
        }
      >
        <DataTableHead table={table} />
        <DataTableBody table={table} />
        <DataTableFooter table={table} />
      </Table>
    </div>
  );
}

"use client";

import { flexRender, type Header, type RowData } from "@tanstack/react-table";

import { DataTableColumnResizer } from "@/components/data-table/head/data-table-column-resizer";
import { DataTableHeadMenu } from "@/components/data-table/head/data-table-head-menu";
import { TableHead, TableHeader, TableRow } from "@/components/ui/table";
import type { TableCoreInstance } from "@/hooks/table/use-table-core";
import { getColumnPinningStyle } from "@/lib/table/column-utils";
import { getAlignClass, getDensityHeadClass } from "@/lib/table/style-utils";
import { cn } from "@/lib/utils";
import { getIsDisplayColumn, resolveSlotProp } from "@/types/table";

interface DataTableHeadProps<TData extends RowData> {
  table: TableCoreInstance<TData>;
}

/**
 * Header string thì bọc dropdown (sắp xếp / ghim / ẩn); header là function thì
 * để nguyên cho caller tự quyết — cùng quy tắc data-grid đang dùng.
 */
function getPlainLabel<TData extends RowData>(
  header: Header<TData, unknown>,
): string | null {
  if (getIsDisplayColumn(header.column.id)) return null;

  const raw = header.column.columnDef.header;
  if (typeof raw === "string") return raw;

  return typeof header.column.columnDef.meta?.label === "string"
    ? header.column.columnDef.meta.label
    : null;
}

export function DataTableHead<TData extends RowData>({
  table,
}: DataTableHeadProps<TData>) {
  const { density } = table.getState();
  const {
    enableColumnResizing,
    enableStickyHeader,
    enableColumnBorders,
    localization,
    slotProps,
  } = table.options;

  const headProps = resolveSlotProp(slotProps.head, { table });
  const headRowProps = resolveSlotProp(slotProps.headRow, { table });

  return (
    <TableHeader
      {...headProps}
      className={cn(
        // Nền/viền mặc định của <thead> (bg-muted, border-b) đã đủ để phân
        // biệt head/body — ở đây chỉ còn lo phần định vị khi cuộn.
        enableStickyHeader && "sticky top-0 z-10",
        headProps?.className,
      )}
    >
      {table.getHeaderGroups().map((headerGroup) => (
        <TableRow
          key={headerGroup.id}
          {...headRowProps}
          className={cn("hover:bg-transparent", headRowProps?.className)}
        >
          {headerGroup.headers.map((header, index) => {
            const cellProps = resolveSlotProp(slotProps.headCell, {
              table,
              header,
            });
            const align = header.column.columnDef.meta?.align;
            const label = getPlainLabel(header);
            const isLast = index === headerGroup.headers.length - 1;

            return (
              <TableHead
                key={header.id}
                colSpan={header.colSpan}
                {...cellProps}
                style={{
                  ...getColumnPinningStyle({
                    column: header.column,
                    withBorder: true,
                    // Khớp nền của <thead> (bg-muted) — nếu để mặc định
                    // var(--background) thì ô ghim sẽ trắng lạc giữa header
                    // xám nhẹ.
                    background: "var(--muted)",
                  }),
                  // Qua CSS var — xem useColumnSizeVars. Dùng --header- (không
                  // phải --col-) vì header có thể colSpan nhiều cột.
                  width: `calc(var(--header-${header.id}-size) * 1px)`,
                  ...cellProps?.style,
                }}
                className={cn(
                  getDensityHeadClass(density),
                  align && getAlignClass(align),
                  // Cột ghim tự vẽ viền bằng box-shadow trong
                  // getColumnPinningStyle — border-e ở đây chỉ dành cho cột
                  // thường (nếu để cả hai, cột ghim kế tiếp sẽ đè mất border-e).
                  enableColumnBorders &&
                    !isLast &&
                    !header.column.getIsPinned() &&
                    "border-e",
                  cellProps?.className,
                )}
              >
                {header.isPlaceholder ? null : label ? (
                  <DataTableHeadMenu
                    header={header}
                    table={table}
                    label={label}
                    localization={localization}
                  />
                ) : (
                  flexRender(
                    header.column.columnDef.header,
                    header.getContext(),
                  )
                )}
                {enableColumnResizing && header.column.getCanResize() && (
                  <DataTableColumnResizer
                    header={header}
                    table={table}
                    label={label ?? header.column.id}
                  />
                )}
              </TableHead>
            );
          })}
        </TableRow>
      ))}
    </TableHeader>
  );
}

"use client";

import type { RowData } from "@tanstack/react-table";

import { TableBody, TableCell, TableRow } from "@/components/ui/table";
import type { TableCoreInstance } from "@/hooks/table/use-table-core";
import { resolveSlotProp } from "@/types/table";

import { DataTableRow } from "./data-table-row";

interface DataTableBodyProps<TData extends RowData> {
  table: TableCoreInstance<TData>;
}

export function DataTableBody<TData extends RowData>({
  table,
}: DataTableBodyProps<TData>) {
  const { density, columnVisibility, columnPinning, columnOrder } =
    table.getState();
  const {
    enableColumnBorders,
    localization,
    renderEmptyRowsFallback,
    slotProps,
  } = table.options;

  const rows = table.getRowModel().rows;
  const bodyProps = resolveSlotProp(slotProps.body, { table });

  if (rows.length === 0) {
    return (
      <TableBody {...bodyProps}>
        <TableRow className="hover:bg-transparent">
          <TableCell
            colSpan={table.getVisibleLeafColumns().length}
            className="h-24 text-center"
          >
            {renderEmptyRowsFallback?.({ table }) ??
              localization.noRecordsToDisplay}
          </TableCell>
        </TableRow>
      </TableBody>
    );
  }

  return (
    <TableBody {...bodyProps}>
      {rows.map((row) => (
        <DataTableRow
          key={row.id}
          table={table}
          row={row}
          rowProps={resolveSlotProp(slotProps.bodyRow, { table, row })}
          slotProps={slotProps}
          density={density}
          columnVisibility={columnVisibility}
          columnPinning={columnPinning}
          columnOrder={columnOrder}
          enableColumnBorders={enableColumnBorders}
        />
      ))}
    </TableBody>
  );
}

